"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[98324],{98324:function(t){t.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/d2131f9266ef4653d1c8655a04236639.jpg\\"\\n  title=\\"Little League\\"\\n  cuisine=\\"카페\\"\\n  address=\\"Container 1,String Bean Alley Queen Victoria Market 513 Elizabeth St North, Melbourne VIC 3000 오스트레일리아\\"\\n  rating=3.5\\n  tags=\\"cafe\\"\\n/>\\n</center>\\n\\n## Review\\n빅토리아 마켓을 일찍 도착해서 마켓이 열리기 전 잠깐의 여유를 위해 입구 쪽 <mark>String Bean Alley</mark>에 위치한 카페에 들렀다.  \\n<mark>롱블랙</mark> 테이크아웃으로 주문 후 잠시 야외 좌석에 앉아 여유를 즐기다 나왔다.  \\n\\n맛이 특별하진 않았지만, 호주 커피는 어딜 가도 기본 이상은 한다는 걸 다시 느꼈다.  \\n\\n```adcard\\n```\\n\\n`League of Honest Coffee` 팀이 운영하는 곳으로 `Padre` 원두를 사용한다고 한다.  \\n\\n마켓 구경 전 짧은 휴식 장소로는 딱이었다.  \\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/d2131f9266ef4653d1c8655a04236639.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Little League\\">\\n<img src=\\"/assets/snippets/location/8e150861904daf6dbae45b1db53f897c.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Little League\\">\\n<img src=\\"/assets/snippets/location/9410e3984408ab27b36613c0e905fa38.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Little League\\">\\n<img src=\\"/assets/snippets/location/2975de3265510fded7074847bf68681f.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Little League\\">\\n<img src=\\"/assets/snippets/location/672677db8e030369240051c44a138d69.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Little League\\">\\n</pictures>\\n"}')}}]);